select 
from biz_pay_channel c
left join biz_pay_provider p on p.provider_code = c.provider_code

    and c.provider_code = #{providerCode}
    and c.channel_code = #{channelCode}
    and c.scene = #{scene}
    and c.status = #{status}

order by c.sort_order, c.channel_id

select 
from biz_pay_channel c
inner join biz_pay_provider p on p.provider_code = c.provider_code
where c.status = '0' and p.status = '0'
and c.provider_code = #{providerCode}
and c.scene = #{scene}
and c.channel_code = #{channelCode}
order by c.weight desc, c.sort_order, c.channel_id

mapper.update:
update biz_pay_channel
display_name = #{displayName}, min_amount = #{minAmount}, max_amount = #{maxAmount}, weight = #{weight}, status = #{status}, sort_order = #{sortOrder}, remark = #{remark}, update_time = sysdate()
where channel_id = #{channelId}
